function atlasElement(tag, attrs, children) {
    var attributes = Object.assign({}, attrs || {});
    // LuCI serializes false as an attribute value; HTML boolean attributes
    // remain enabled whenever present, even when their value is "false".
    ['disabled', 'checked', 'selected', 'readonly', 'multiple', 'required', 'autofocus', 'hidden', 'open'].forEach(function(key) {
        if (attributes[key] === false) delete attributes[key];
    });
    // LuCI E() accepts a flat child list. Nested arrays otherwise become
    // literal "[object HTMLDivElement]" text and their controls disappear.
    var flattened=[];
    function append(child){if(Array.isArray(child))child.forEach(append);else if(child!=null)flattened.push(child);}
    append(children);
    return E(tag, attributes, flattened);
}
function node(tag, cls, children, attrs) {
    var element=atlasElement(tag, Object.assign({ 'class': cls || '' }, attrs || {}), children);
    if(tag==='table' && cls==='at-table') {
        var headings=Array.from(element.querySelectorAll('thead th')).map(function(x){return x.textContent;});
        Array.from(element.querySelectorAll('tbody tr')).forEach(function(row){Array.from(row.children).forEach(function(cell,i){cell.setAttribute('data-label',headings[i] || '');});});
    }
    if(tag==='label' && cls==='at-checkbox') {
        var title=element.textContent;
        var control=Array.from(element.children || []).find(function(x){return (x.tagName || x.tag || '').toLowerCase()==='input';});
        var help=atlasHelpBox(title,null,control);
        // Keep interactive disclosures outside labels: opening help must not
        // accidentally toggle the checkbox, and help needs its own full row.
        return atlasElement('div',{'class':'at-checkbox-field'},[element,help]);
    }
    return element;
}
function atlasAdblockMatch(item,preset) {
    return item.policy==='dnsblock' && !item.section && !item.interface && (item.adblock_preset===preset.key || item.url===preset.url);
}
function atlasRouteName(tag,data) {
    var labels={direct:'Напрямую','policy-block':'Заблокировано',proxy:'Общий прокси',auto:'Общий автовыбор'};
    if(labels[tag])return labels[tag];
    var profile=(data.nodes || []).find(function(n){return n.key===tag;});
    if(profile)return profile.name;
    var pool=(data.subscriptions || []).find(function(s){return tag==='pool_'+s.id || tag==='auto_'+s.id;});
    if(pool)return (tag.indexOf('auto_')===0 ? 'Автовыбор: ' : 'Подписка: ')+pool.name;
    var section=(data.settings.sections || []).find(function(s){return tag.indexOf('section_'+s.id+'_')===0;});
    if(section){var member=(data.nodes || []).find(function(n){return tag==='section_'+section.id+'_'+n.key;});return member ? member.name+' · '+section.name : 'Секция: '+section.name;}
    return tag;
}
function atlasRouteChain(tags,data) {
    return (tags || []).map(function(tag){return atlasRouteName(tag,data);}).filter(function(name,index,names){return !index || name!==names[index-1];}).join(' → ') || 'неизвестно';
}
function atlasMergeSectionLists(lists,overrides) {
    var original=lists || [],owners=Object.create(null),result=[];
    Object.keys(overrides || {}).forEach(function(id){owners[id]={rows:overrides[id],ids:Object.create(null),updated:Object.create(null),added:[],last:-1};});
    original.forEach(function(item,index){
        if(!Object.prototype.hasOwnProperty.call(owners,item.section))return;
        var owner=owners[item.section];owner.last=index;if(item.id)owner.ids[item.id]=true;
    });
    Object.keys(owners).forEach(function(id){
        var owner=owners[id];
        owner.rows.forEach(function(item){if(item.id && owner.ids[item.id])owner.updated[item.id]=item;else owner.added.push(item);});
    });
    function append(item){result.push(Object.assign({},item));}
    original.forEach(function(item,index){
        if(!Object.prototype.hasOwnProperty.call(owners,item.section)){append(item);return;}
        var owner=owners[item.section];
        // Editing a source replaces it in place: moving a broad list ahead of
        // a specific site list would change routing even after a name edit.
        if(item.id && Object.prototype.hasOwnProperty.call(owner.updated,item.id))append(owner.updated[item.id]);
        if(index===owner.last)owner.added.forEach(append);
    });
    Object.keys(owners).forEach(function(id){if(owners[id].last<0)owners[id].rows.forEach(append);});
    return result;
}
function atlasSectionChoice(section,data,staged) {
    var settings=data.settings || {},choices=settings.section_choices || {},prefix='section_'+section.id+'_';
    var oldTag=Array.isArray(section.pools) || !section.name ? '' : section.pool ? 'pool_'+section.pool : 'proxy';
    var choice=staged || choices[prefix+'control'] || choices[oldTag] || (oldTag==='proxy' ? settings.selected : 'auto') || 'auto';
    if(choice==='auto' || /^auto_/.test(choice) || choice===prefix+'auto')return 'auto';
    return choice.indexOf(prefix)===0 ? choice.slice(prefix.length) : choice;
}
function atlasSectionConnection(section,data,staged) {
    if(section.policy!=='proxy')return '';
    if(section.outbound_config_set || (section.outbound_config || []).length)return 'Свой JSON выход';
    var choice=atlasSectionChoice(section,data,staged),profile=(data.nodes || []).find(function(n){return n.key===choice;});
    var source='Общий пул';
    if(Array.isArray(section.pools))source=section.pools.length ? 'Подписок: '+section.pools.length : 'Все подписки';
    else if(section.pool){var subscription=(data.subscriptions || []).find(function(s){return s.id===section.pool;});source=subscription ? subscription.name : 'Подписка недоступна';}
    return (choice==='auto' ? 'Автовыбор' : 'Закреплён: '+(profile ? profile.name : 'сохранённый профиль'))+' · '+source;
}

function label(t) { return document.createTextNode(String(t)); }
function pill(t, cls) { return node('span', 'at-pill ' + (cls || ''), label(t)); }
function date(t) { return t ? new Date(t * 1000).toLocaleString('ru-RU') : 'Ещё не обновлялась'; }
function liveDate(t) { return t ? new Date(t).toLocaleString('ru-RU') : 'Нет замера'; }
function liveMeasurementFresh(measurement, interval) {
    var stamp=Date.parse(measurement && measurement.checked_at),age=(Date.now()-stamp)/1000;
    return Number.isFinite(stamp) && age>=-60 && age<=Math.max(180,(Number(interval)||60)*3);
}
function atlasProfileHealth(data) {
    var runtime=data.runtime || {},nodes=data.nodes || [],measurements=runtime.measurements || {};
    var counts={passed:0,failed:0,stale:0,missing:0,excluded:0};
    nodes.forEach(function(n){
        if(n.eligible===false){counts.excluded++;return;}
        var live=measurements[n.key];
        if(!live){counts.missing++;return;}
        if(!liveMeasurementFresh(live,(data.settings || {}).auto_interval_seconds)){counts.stale++;return;}
        if(live.ok && Number(live.latency_ms)>0)counts.passed++;else counts.failed++;
    });
    if(!data.running)counts.summary='Автопроверка: Atlas остановлен';
    else if(!runtime.available)counts.summary='Автопроверка: нет данных от движка';
    else {
        var parts=[];
        if(counts.passed)parts.push('отвечают '+counts.passed);
        if(counts.failed)parts.push('не ответили '+counts.failed);
        if(counts.stale)parts.push('устаревших замеров '+counts.stale);
        if(counts.missing)parts.push('без замера '+counts.missing);
        if(counts.excluded)parts.push('исключены фильтром '+counts.excluded);
        counts.summary='Автопроверка: '+(parts.length ? parts.join(' · ') : 'нет профилей');
    }
    return counts;
}
function bytes(n) {
    n = Number(n || 0);
    return n >= 1073741824 ? (n / 1073741824).toFixed(1) + ' ГиБ' : (n / 1048576).toFixed(1) + ' МиБ';
}
function result(promise) {
    return promise.then(function(r) { if (!r || !r.ok) throw new Error(r && r.error || 'Нет ответа от Atlas'); return r; });
}
function error(e) { ui.addNotification(null, node('p', '', label(e.message || String(e))), 'error'); }
function lines(value) { return value.split(/[\n,]+/).map(function(s) { return s.trim(); }).filter(Boolean); }

function atlasDisclosures(root) {
    var occurrences={};
    return Array.from(root.querySelectorAll('details')).map(function(element){
        var summary=Array.from(element.children || []).find(function(child){return (child.tagName || child.tag || '').toLowerCase()==='summary';});
        var name=summary ? (summary.getAttribute ? summary.getAttribute('aria-label') : (summary.attributes || {})['aria-label']) || summary.textContent : '';
        var occurrence=occurrences[name] || 0;occurrences[name]=occurrence+1;
        return {key:name+'#'+occurrence,element:element};
    });
}

